import json
from typing import Any
from fastmcp import Server
from fastmcp.mcp_server import RequestContext
import httpx


def create_openapi_mcp_server(
    spec: dict,
    client: httpx.AsyncClient,
    server_name: str = "openapi-server"
) -> Server:
    """Create an MCP server from an OpenAPI 3.0 spec and httpx.AsyncClient."""

    server = Server(server_name)

    paths = spec.get("paths", {})

    for path_key, path_item in paths.items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path_key}".replace("/", "_").replace("{", "").replace("}", ""))
            description = operation.get("summary") or operation.get("description", "")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            tool_properties = {}
            required_params = []

            for param in parameters:
                param_name = param.get("name")
                param_schema = param.get("schema", {})
                param_type = param_schema.get("type", "string")

                json_type = "string"
                if param_type == "integer":
                    json_type = "integer"
                elif param_type == "number":
                    json_type = "number"
                elif param_type == "boolean":
                    json_type = "boolean"
                elif param_type == "array":
                    json_type = "array"

                tool_properties[param_name] = {
                    "type": json_type,
                    "description": param.get("description", "")
                }

                if param.get("required", False):
                    required_params.append(param_name)

            if request_body:
                tool_properties["body"] = {
                    "type": "object",
                    "description": "Request body"
                }
                if request_body.get("required", False):
                    required_params.append("body")

            async def make_tool_func(
                method_: str,
                path_template: str,
                params_list: list,
                has_body: bool
            ):
                async def tool_func(ctx: RequestContext, **kwargs) -> str:
                    url = path_template
                    query_params = {}
                    headers = {}
                    body_data = None

                    for param in params_list:
                        param_name = param.get("name")
                        param_in = param.get("in", "query")

                        if param_name in kwargs:
                            value = kwargs[param_name]
                            if param_in == "path":
                                url = url.replace(f"{{{param_name}}}", str(value))
                            elif param_in == "query":
                                query_params[param_name] = value
                            elif param_in == "header":
                                headers[param_name] = str(value)

                    if has_body and "body" in kwargs:
                        if isinstance(kwargs["body"], str):
                            body_data = json.loads(kwargs["body"])
                        else:
                            body_data = kwargs["body"]

                    try:
                        response = await client.request(
                            method_.upper(),
                            url,
                            params=query_params,
                            json=body_data,
                            headers=headers
                        )
                        return json.dumps({
                            "status_code": response.status_code,
                            "body": response.json() if response.headers.get("content-type", "").startswith("application/json") else response.text
                        })
                    except Exception as e:
                        return json.dumps({"error": str(e)})

                return tool_func

            tool_func = make_tool_func(method, path_key, parameters, bool(request_body))

            server.add_tool(
                tool_func,
                name=operation_id,
                description=description,
                input_schema={
                    "type": "object",
                    "properties": tool_properties,
                    "required": required_params
                }
            )

    return server


async def main():
    spec = {
        "openapi": "3.0.0",
        "info": {"title": "Test API", "version": "1.0.0"},
        "paths": {
            "/users/{id}": {
                "get": {
                    "operationId": "getUser",
                    "summary": "Get user by ID",
                    "parameters": [
                        {"name": "id", "in": "path", "required": True, "schema": {"type": "integer"}}
                    ]
                }
            }
        }
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = create_openapi_mcp_server(spec, client)
        await server.run()


if __name__ == "__main__":
    import asyncio
    asyncio.run(main())

